"""Offline visual review of actual P05 local QA screens; no live/private data embedded."""
from pathlib import Path
from PIL import Image
import base64
root=Path(__file__).resolve().parent.parent
output=root.parent/'deliverables/hadiran-orders-finance.html'
assets=output.parent/'finance-assets';assets.mkdir(parents=True,exist_ok=True)
def shot(name,height):
 im=Image.open(root/'qa'/name);im=im.crop((0,0,im.width,min(height,im.height)));target=assets/name;im.save(target,optimize=True)
 return 'data:image/png;base64,'+base64.b64encode(target.read_bytes()).decode()
regular=base64.b64encode((root/'src/app/fonts/IRANSharp-Regular.woff2').read_bytes()).decode()
bold=base64.b64encode((root/'src/app/fonts/IRANSharp-Bold.woff2').read_bytes()).decode()
views=[('گزارش تسویه','finance-report-light.png',1750,1100,'بخش آغاز گزارش: دورهٔ شمسی، واحدهای جدا، جمع قابل پیگیری و هشدار تسویهٔ بی‌تاریخ.'),('صف سفارش / موبایل','finance-orders-mobile-dark.png',2200,430,'نمای واقعی موبایل تاریک: فیلتر، تفکیک وضعیت و صف بررسی.'),('رویداد و مبلغ ثبت‌شده','finance-order-history-light.png',1700,1100,'پس از تأیید آزمایشی: مبلغ سفارش و ثبت عامل/زمان؛ بدون تاریخچهٔ فرضی.'),('خریدهای عضو','finance-personal-mobile.png',2400,430,'حساب عضو: فقط خریدها و دسترسی خودش، نه اطلاعات خریدار دیگر.')]
buttons=''.join(f'<button onclick="show({i})" aria-pressed="{str(i==0).lower()}">{label}</button>' for i,(label,*_) in enumerate(views))
figures=''.join(f'<figure {"hidden" if i else ""}><figcaption>{caption}</figcaption><img alt="{label}" src="{shot(file,height)}" style="max-width:{width}px"></figure>' for i,(label,file,height,width,caption) in enumerate(views))
html='''<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>هادیران · مرحلهٔ ۵ · سفارش و گزارش مالی</title><style>
@font-face{font-family:IRANSharp;src:url(data:font/woff2;base64,REGULAR);font-weight:400}@font-face{font-family:IRANSharp;src:url(data:font/woff2;base64,BOLD);font-weight:700}*{box-sizing:border-box}body{margin:0;background:#fbf9f5;color:#151a22;font:15px/2 IRANSharp,system-ui}header,main{max-width:1200px;margin:auto;padding:28px 24px}h1{font-size:27px;margin:8px 0}header>span{color:#0b6f6b;font-size:13px}p{margin:10px 0;color:#565a61}.notice{border-right:3px solid #0f8f8a;padding:10px 18px;background:#edf3f0;border-radius:4px;font-size:13px}.facts{display:flex;gap:10px;flex-wrap:wrap;font-size:12px;color:#565a61;margin-top:18px}.facts span{border:1px solid #e8e2d6;padding:5px 10px;border-radius:5px}nav{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}button{font:inherit;border:1px solid #d4cdbf;background:transparent;padding:7px 14px;border-radius:5px;cursor:pointer;color:inherit}button[aria-pressed=true]{background:#0b6f6b;border-color:#0b6f6b;color:white}button:focus-visible{outline:2px solid #0b6f6b;outline-offset:4px}figure{margin:0}figure[hidden]{display:none}figcaption{font-size:13px;color:#636973;margin-bottom:16px}img{width:100%;height:auto;display:block;margin:auto;border:1px solid #e8e2d6;border-radius:8px}details{margin-top:16px;font-size:13px}summary{cursor:pointer}code{direction:ltr;unicode-bidi:embed;font-size:12px}@media(max-width:600px){h1{font-size:22px}header,main{padding:20px 16px}button{font-size:13px}}</style>
<header><span>هادیران / مرحلهٔ ۵ / نسخهٔ داخلی</span><h1>از سفارش تا تسویه؛ روشن و قابل پیگیری.</h1><p>مرکز سفارش مدیر، گزارش تسویه‌ها و تاریخچهٔ خرید عضو، در همان پوستهٔ فعلی هادیران. گراف معرف و صفحهٔ اصلی محفوظ‌اند.</p><p class="notice">این‌ها تصاویر اجرای واقعی برنامه با داده‌های صریحاً آزمایشی در PostgreSQL محلی هستند؛ فروش و پرداخت واقعی محیط اصلی نیستند. این فایل مرور تصویری است، نه فرم پرداخت.</p><div class="facts"><span>نمایش دقیق تومان / ذخیرهٔ ریال</span><span>دورهٔ شمسی / وقت تهران</span><span>تأیید و دسترسی در یک تراکنش</span><span>۹ گروه API + ۶ گروه unit + ۷ گروه مرورگر</span><span>۷۲ حالت نمایش + متن ۲۰۰٪</span></div>
<details><summary>دامنه و مسیرهای مرور</summary><p>مدیر: <code>/workspace/shop/orders</code> و <code>/workspace/finance</code> · عضو: <code>/account/purchases</code> در پیش‌نمایش داخلی. داده‌های مدیر فقط با مجوز owner؛ خرید عضو فقط از نشست خودش.</p><p>عدد تسویه، شمارهٔ پیگیری یا سود خالص نیست. واحدها مخلوط نمی‌شوند و هر مبلغ به سفارش‌های همان فیلتر برمی‌گردد. تکرار هم‌زمان و خطای عمدی میانی، دسترسی یا اثر مالی تکراری/نیمه‌تمام نساختند.</p><p>فیلتر آزمون هنوز نیازمند رابطهٔ واقعی خرید آزمون با سفارش است و حدسی ساخته نشده. کیف پول، درگاه، استرداد، استقرار و انتقال Drive اجرا نشده‌اند.</p></details><nav aria-label="نماهای مرحلهٔ ۵">BUTTONS</nav></header><main>FIGURES</main><script>function show(n){document.querySelectorAll('figure').forEach((el,i)=>el.hidden=i!==n);document.querySelectorAll('nav button').forEach((el,i)=>el.setAttribute('aria-pressed',String(i===n)))}</script></html>'''
for key,value in [('REGULAR',regular),('BOLD',bold),('BUTTONS',buttons),('FIGURES',figures)]:html=html.replace(key,value)
output.write_text(html);print(output)
